<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\User; use Pterodactyl\Models\Model; use Pterodactyl\Models\Server; use Illuminate\Database\Eloquent\Relations\BelongsTo; class DriveBackup extends Model { public const RESOURCE_NAME = 'drive_backup'; protected $table = 'dezerx_drive_backups'; protected $guarded = ['id']; protected $casts = [ 'server_id' => 'int', 'user_id' => 'int', 'interval_hours' => 'int', 'keep' => 'int', 'last_run_at' => 'datetime', 'refresh_token' => 'encrypted', ]; protected $hidden = ['refresh_token']; public static array $validationRules = [ 'server_id' => 'required|int|exists:servers,id', 'user_id' => 'required|int|exists:users,id', 'refresh_token' => 'required|string', 'interval_hours' => 'int|between:0,168', 'keep' => 'int|between:1,50', ]; public function isDue(): bool { if ($this->interval_hours <= 0) { return false; } return $this->last_run_at === null || $this->last_run_at->addHours($this->interval_hours)->isPast(); } public function server(): BelongsTo { return $this->belongsTo(Server::class); } public function user(): BelongsTo { return $this->belongsTo(User::class); } } 